def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v not in (0, 3)), None)
    seen = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == color}
    stack = list(seen)
    while stack:
        r,c = stack.pop()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and grid[nr][nc]==0:
                seen.add((nr,nc)); stack.append((nr,nc))
    return [[color if (r,c) in seen else v for c,v in enumerate(row)] for r,row in enumerate(grid)]
